#!/usr/bin/env python3
# d313_4b3_parche.py — DAY313, paso 4b.3 de DEBT-ETCD-HA-TLS-RAFT-001 (un solo uso: NO se commitea).
# Registro de componentes en el etcd real (gRPC + TLS, etcd-cpp-apiv3 v0.15.3) con IRegistryStore: EtcdRegistryStore y
# MemoriaRegistryStore (almacen.modo "memoria" = transición del defender hasta el paso 6). RegistroComponentes: un solo
# mutex, lectura de etcd con la copia como respaldo, escrituras 503 si etcd no responde, muerto se marca y revive,
# época persistida, monitor que para al instante; canal gRPC nuevo tras un fallo. Nombre de /register y /unregister
# == CN (403). Fuera el unordered_map sin mutex, auto_restart + system() y los métodos que no hacían nada.
# Uso (Mac, raíz del repo, rama feat/etcd-mtls-vault con 4b.2 v2 aplicado, commiteado o no):
#   python3 -I scripts/d313_4b3_parche.py --check    valida todo y no escribe nada
#   python3 -I scripts/d313_4b3_parche.py --apply    valida todo y, solo si todo cuadra, escribe
# Valida ANTES de escribir: sha256 de partida de cada fichero modificado, que los nuevos no existan, y "ya aplicado"
# (todos con el sha256 final -> no hace nada, rc 0). Mezcla de estados -> no escribe nada, rc 1.
# Escribe cada fichero por tmp + rename y comprueba su sha256 final.
import base64, hashlib, os, sys
FICHEROS = [{'ruta': 'etcd-server/CMakeLists.txt', 'ini': '6ffa5329711bd3e6d7ffe60f6616765cb405a7999031a1b8ac58b1599be99ed4', 'otros_ini': [], 'fin': '7f58e6ab68f2dde969b590c047824bc2da72b613905a19423cd07a4ae24d30d8', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/config/etcd-server.etcd-vm.json', 'ini': '470a3e3acb865ea8e69b879d0fc592bcc8d671021309957d4dbb1ef9e791e4c6', 'otros_ini': [], 'fin': 'fb4b75c053fd8e40275752e7eec43db3fdc6b360af812cbbcf029391bd72613a', 'modo': '0o644', 'b64': ''}, {'ruta': 'etcd-server/config/etcd-server.json', 'ini': '19f7f98601d5f632511726dbff145bc7fa72b1ec0e594439ef99615b21458cd0', 'otros_ini': [], 'fin': '8d7f9650fcaf127794b1203bad60324b81ecb5d6bbeb89a6018c9e1f4141c153', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/include/etcd_server/component_registry.hpp', 'ini': 'ba1a08ed11dfe12f1172a28bc4285bc4ff94c1d8e3dd75e9c3e1b0f5806d34ce', 'otros_ini': [], 'fin': 'bad491745f7b0f0c6522712e9c85745cc87ca9dc183d25b7df9266f4b30889ca', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/include/etcd_server/etcd_registry_store.hpp', 'ini': None, 'otros_ini': [], 'fin': 'b0dc0b946ccabaa54f574924e9cdd3d5d62a1d66e384fb516a56e3681dfb8034', 'modo': '0o644', 'b64': ''}, {'ruta': 'etcd-server/include/etcd_server/etcd_server.hpp', 'ini': '48a6028a670da21d072040609e2c44a3961d809d637e3daca225b6ad6a1ec1ef', 'otros_ini': [], 'fin': 'da8b7d8e174ee3ea7de25de40ccc4d21f71ac90e95b1ea9761bede1826c71348', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/include/etcd_server/etcd_server_almacen.hpp', 'ini': None, 'otros_ini': [], 'fin': '9aafde81ad0f8f071ac746e07e41d1561a1a2530b0633c301765addcb0078a4a', 'modo': '0o644', 'b64': ''}, {'ruta': 'etcd-server/include/etcd_server/registro_componentes.hpp', 'ini': None, 'otros_ini': [], 'fin': 'e84d2cfbfab3b1b3bbdd5c641b31947b7a7b3bd7e69b0ada1e58dbf0344948c8', 'modo': '0o644', 'b64': ''}, {'ruta': 'etcd-server/src/component_registry.cpp', 'ini': 'a2c89a16d8d0fd19b9f8ffe8380a90065b91049fa0e8318f949235b931f2ba42', 'otros_ini': [], 'fin': 'bcc1152ef0bf9093262935233cb575321d7166f72cb6f35dea97a20126675ea2', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/src/etcd_registry_store.cpp', 'ini': None, 'otros_ini': [], 'fin': '6248a3434f635745bb0f5833a0bdd9c7ed7b570cf20778515acc95bacceb78c5', 'modo': '0o644', 'b64': ''}, {'ruta': 'etcd-server/src/etcd_server.cpp', 'ini': 'ff776031c10e06838a0d3e0b8a52ee9920fa43fcc363345d0fe692f4e1326f8e', 'otros_ini': [], 'fin': '4dc188938efb95e11edb05e372d143613960cbd834f04b1642b2427dc2009ad2', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/src/main.cpp', 'ini': '7b0fdb7fceb56ae405e0e85192344d12eeaaf64005022b6cf9d5da2a981d6506', 'otros_ini': [], 'fin': 'bba54c95ac3daa325af7c861632bf1470365064b9e2cea656ffd4c7eebb20490', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/tests/test_etcd_server_authz.cpp', 'ini': '9a719b6e1d2f87cfad307b5bbac89aba79b06f1d3ea9f41c9c399ec81ee1a44b', 'otros_ini': [], 'fin': 'f62905180dac50be50c0c80f4e64d3a7cd4a506f55f0a3358a28b603e7eef3f3', 'modo': '0o644', 'b64': ''}, {'ruta': 'etcd-server/tests/test_registro_componentes.cpp', 'ini': None, 'otros_ini': [], 'fin': '7cb4ed74e1840e5ff1f48aabe42c97f697bc02362a169d012d791d214e892035', 'modo': '0o644', 'b64': ''}, {'ruta': 'scripts/etcd_ha/d313_es_vm.sh', 'ini': '73f49ac2b6716b3562da23e7fdf1b944496b6b716388c7a472313cf1308f24ee', 'otros_ini': [], 'fin': '03d1e7574f8ed83654a55a2a0cc03a16e8801c39ebd4a809715d715eccffffaa', 'modo': '0o755', 'b64': ''}, {'ruta': 'scripts/etcd_ha/d313_registro_medir.sh', 'ini': None, 'otros_ini': [], 'fin': 'f1f50c3e29b3bdc36e6b3a1304fb64212f944158a8a5bfba0b786c7592d3a32d', 'modo': '0o644', 'b64': ''}]
def sha(p):
    with open(p, 'rb') as f: return hashlib.sha256(f.read()).hexdigest()
def main():
    if len(sys.argv) != 2 or sys.argv[1] not in ('--check', '--apply'):
        print('uso: python3 -I scripts/d313_4b3_parche.py --check|--apply'); return 2
    if not (os.path.isfile('Vagrantfile') and os.path.isdir('.git') and os.path.isdir('etcd-server')):
        print('[D313B-PARCHE] FALLA: no estoy en la raíz del repo'); return 1
    aplicados = pendientes = corregir = 0; errores = []
    for e in FICHEROS:
        r = e['ruta']; existe = os.path.exists(r)
        actual = sha(r) if existe else None
        if actual == e['fin']:
            aplicados += 1; estado = 'ya aplicado'
            if e['otros_ini']: corregir += 1
        elif e['ini'] is None and not existe:
            pendientes += 1; estado = 'nuevo, pendiente'
        elif e['ini'] is not None and actual == e['ini']:
            pendientes += 1; estado = 'partida OK, pendiente'
        elif existe and actual in e['otros_ini']:
            pendientes += 1; estado = 'partida = parcheador anterior (sin corrección GCC 12), pendiente'
        else:
            estado = 'NO CUADRA'
            errores.append('%s: sha256 %s, esperado partida %s o final %s' % (
                r, (actual or 'no existe')[:16], (e['ini'] or 'no existe')[:16], e['fin'][:16]))
        print('[D313B-PARCHE] %-58s %s' % (r, estado))
    if errores:
        for x in errores: print('[D313B-PARCHE] FALLA: ' + x)
        print('[D313B-PARCHE] no se escribe nada'); return 1
    if pendientes == 0:
        print('[D313B-PARCHE] RESULTADO: ya aplicado (%d/%d), no se hace nada' % (aplicados, len(FICHEROS))); return 0
    previos = sum(1 for e in FICHEROS if os.path.exists(e['ruta']) and sha(e['ruta']) in e['otros_ini'])
    if aplicados and not (previos == pendientes and aplicados + previos == len(FICHEROS)):
        print('[D313B-PARCHE] FALLA: mezcla de estados (%d aplicados, %d pendientes): no se escribe nada' % (aplicados, pendientes)); return 1
    if sys.argv[1] == '--check':
        print('[D313B-PARCHE] RESULTADO --check: %d ficheros listos para aplicar (%d ya en su estado final); nada escrito' % (pendientes, aplicados)); return 0
    for e in FICHEROS:
        r = e['ruta']; d = os.path.dirname(r)
        if os.path.exists(r) and sha(r) == e['fin']: continue
        if d: os.makedirs(d, exist_ok=True)
        datos = base64.b64decode(e['b64'])
        tmp = r + '.d313btmp'
        with open(tmp, 'wb') as f: f.write(datos)
        os.chmod(tmp, int(e['modo'], 8)); os.replace(tmp, r)
        if sha(r) != e['fin']:
            print('[D313B-PARCHE] FALLA: %s escrito pero su sha256 no es el final' % r); return 1
    print('[D313B-PARCHE] RESULTADO --apply: %d ficheros escritos, sha256 final OK en los %d' % (pendientes, len(FICHEROS))); return 0
sys.exit(main())
